{
  "application": "poster-generation",
  "case_id": "case-health-malaria-global-burden-progress",
  "language": "en",
  "source_brief": "/app/benchmark/source_brief.md",
  "poster": {
    "aspect_ratio": "A1-portrait",
    "audience": "public-exhibition",
    "tone": "data-forward, engaging",
    "venue": null
  },
  "brief": {
    "title": "Malaria: A Preventable Killer — Global Progress and the Road Ahead",
    "one_liner": "Over half a million people still die from malaria each year, most of them children, yet humanity has made remarkable progress eliminating the disease from half the world.",
    "goal": "Viewers should understand the scale of malaria's toll on children and vulnerable populations, recognize the dramatic historical progress in eliminating the disease from many regions, and appreciate the interventions — bednets, vaccines, and economic development — that can continue driving progress."
  },
  "sections": [
    {
      "id": "burden",
      "title": "The Burden: Who Malaria Kills",
      "objective": "Convey the scale of annual deaths, emphasizing that children under 5 are the most vulnerable group and Africa bears the overwhelming majority of the burden."
    },
    {
      "id": "historical-progress",
      "title": "From Half the World to a Quarter",
      "objective": "Show that malaria was once endemic across ~50% of the world's land surface and has been eliminated from many regions, shrinking to ~27% by 2002. Emphasize that malaria is not inherently a 'tropical disease' but one that was eliminated everywhere except the tropics."
    },
    {
      "id": "death-trends",
      "title": "Death Toll Trends: 2000–2023",
      "objective": "Present the decline in deaths from 2000 to 2015, the stalling of progress, and the COVID-19 setback in 2020, using WHO and IHME estimates."
    },
    {
      "id": "interventions",
      "title": "What Works: Tools to Beat Malaria",
      "objective": "Highlight the three key drivers of elimination — insecticide-treated bednets, public health measures/vaccines, and economic development — as actionable levers for continued progress."
    },
    {
      "id": "call-to-action",
      "title": "1,320 Children Every Day",
      "objective": "Leave viewers with the urgency: 1,320 children die from this preventable disease daily, and continued investment can change that."
    }
  ],
  "metrics": [
    {
      "label": "Daily child deaths from malaria",
      "value": "~1,320",
      "context": "Preventable deaths each day"
    },
    {
      "label": "Annual malaria deaths (2010s)",
      "value": ">500,000",
      "context": "Per year, majority children"
    },
    {
      "label": "Most affected region",
      "value": "Africa",
      "context": "Vast majority of global malaria deaths"
    },
    {
      "label": "Historic malaria land coverage (~1900)",
      "value": "~50%",
      "context": "Of world's land surface"
    },
    {
      "label": "Malaria land coverage by 2002",
      "value": "~27%",
      "context": "Reduced by nearly half"
    },
    {
      "label": "Most vulnerable age group",
      "value": "Children under 5",
      "context": "Highest share of malaria deaths globally"
    }
  ]
}

