<body>
  <div id="container"></div>
  <script src="/app/vendor/infographic.min.js"></script>
  <script>
  (async () => {
    const infographic = new AntVInfographic.Infographic({
      container: '#container',
      width: '794',   // A1 portrait width in px at 96dpi
      height: '1123', // A1 portrait height in px at 96dpi
    });

    const syntax = `infographic list-grid-ribbon-card
data
  title Malaria: A Preventable Killer
  desc Over half a million people still die from malaria each year — most of them children under five in Africa. Yet humanity has made extraordinary progress eliminating this disease from half the world.
  lists
    - label 1,320
      desc CHILDREN DIE FROM MALARIA EVERY SINGLE DAY
      icon heart break
      value 1320
    - label >500,000
      desc ANNUAL MALARIA DEATHS IN THE 2010s
      icon skull cross
      value 500000
    - label Africa
      desc BEARS THE OVERWHELMING MAJORITY OF THE BURDEN
      icon globe africa
      value 1
    - label Children Under 5
      desc ARE THE MOST VULNERABLE GROUP
      icon baby
      value 1
theme
  palette #1a2744 #f59e0b #ef4444 #10b981 #60a5fa
  base
    background #0d1f3c
    text font-family Inter
  stylize
    rough false
`;

    infographic.render(syntax);

    await document.fonts?.ready;

    // Export as PNG via canvas
    const page = await infographic.toDataURL({ type: 'png' });
    console.log('Rendered');

    // For SVG export:
    // const svg = await infographic.toDataURL({ type: 'svg' });
  })();
  </script>
</body>
