(async () => {
  const browser = await puppeteer.launch({ headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  const page = await browser.newPage();
  page.setDefaultTimeout(10000);
  await page.goto('file:///app/malaria-poster.html', { waitUntil: 'domcontentloaded' });
  await new Promise(r => setTimeout(r, 3000));
  const title = await page.title();
  console.log('Title:', title);
  const hasContainer = await page.evaluate(() => !!document.getElementById('container'));
  console.log('Has container:', hasContainer);
  await browser.close();
  console.log('Done');
})().catch(e => { console.log('Error:', e.message.slice(0,200)); process.exit(0); });
" 2>&1

